using System.Collections.Generic;
using UnityEngine;
using TMPro;

/// The menu design system in one place: palette, sprite lookup and the UI
/// font.  Every menu (baked scenes AND the few runtime overlays) pulls from
/// here, so the whole game reads as one product.
///
/// Sprites live as PNGs in Resources/UI (generated by the scene builders from
/// UISpriteFactory — replace any PNG with your own art, same name, and every
/// menu picks it up).  If a PNG is missing the same shape is generated in
/// memory, so nothing ever renders blank.
///
/// Font: drop a TMP font asset at Resources/UI/Fonts/MenuFont to brand the
/// menus.  Otherwise the OS "Bahnschrift" face (Windows' DIN-style font) is
/// loaded at runtime — used, not redistributed — falling back to TMP's default.
public static class UITheme
{
    // ── Palette ───────────────────────────────────────────────────────────────
    public static readonly Color Ink        = new Color(0.030f, 0.026f, 0.055f, 1f);
    public static readonly Color Panel      = new Color(0.045f, 0.040f, 0.082f, 0.88f);
    public static readonly Color PanelLite  = new Color(0.090f, 0.078f, 0.150f, 0.92f);
    public static readonly Color Row        = new Color(0.062f, 0.054f, 0.110f, 0.80f);
    public static readonly Color RowFocus   = new Color(0.165f, 0.105f, 0.300f, 0.96f);
    public static readonly Color Accent     = new Color(0.690f, 0.420f, 1.000f, 1f);   // #B06BFF
    public static readonly Color AccentHot  = new Color(0.870f, 0.680f, 1.000f, 1f);
    public static readonly Color AccentDeep = new Color(0.330f, 0.160f, 0.640f, 1f);
    public static readonly Color Cyan       = new Color(0.360f, 0.860f, 1.000f, 1f);
    public static readonly Color Gold       = new Color(1.000f, 0.800f, 0.300f, 1f);
    public static readonly Color Silver     = new Color(0.820f, 0.860f, 0.920f, 1f);
    public static readonly Color Bronze     = new Color(0.900f, 0.580f, 0.360f, 1f);
    public static readonly Color Good       = new Color(0.400f, 0.950f, 0.600f, 1f);
    public static readonly Color Bad        = new Color(1.000f, 0.380f, 0.420f, 1f);
    public static readonly Color Text       = new Color(0.955f, 0.945f, 0.990f, 1f);
    public static readonly Color TextDim    = new Color(0.650f, 0.630f, 0.750f, 1f);
    public static readonly Color TextFaint  = new Color(0.430f, 0.410f, 0.530f, 1f);
    public static readonly Color Line       = new Color(1f, 1f, 1f, 0.09f);

    // Gamepad face-button colours (Xbox convention) for prompt glyphs.
    public static readonly Color PadA = new Color(0.36f, 0.78f, 0.28f, 1f);
    public static readonly Color PadB = new Color(0.90f, 0.28f, 0.26f, 1f);
    public static readonly Color PadX = new Color(0.22f, 0.50f, 1.00f, 1f);
    public static readonly Color PadY = new Color(1.00f, 0.78f, 0.18f, 1f);

    public static Color Alpha(Color c, float a) { c.a = a; return c; }

    /// Podium colours: gold / silver / bronze, then plain.
    public static Color PlaceColor(int pos) => pos switch
    {
        1 => Gold, 2 => Silver, 3 => Bronze, _ => TextDim,
    };

    public static string Ordinal(int n)
    {
        if (n <= 0) return "-";
        int m100 = n % 100;
        string suf = (m100 >= 11 && m100 <= 13) ? "TH"
                   : (n % 10) switch { 1 => "ST", 2 => "ND", 3 => "RD", _ => "TH" };
        return n + suf;
    }

    /// Elevation → colour for track previews: low cyan → violet → high gold.
    public static Color HeightTint(float t)
    {
        t = Mathf.Clamp01(t);
        return t < 0.5f ? Color.Lerp(Cyan, Accent, t * 2f)
                        : Color.Lerp(Accent, Gold, (t - 0.5f) * 2f);
    }

    // ── Sprites ───────────────────────────────────────────────────────────────
    static readonly Dictionary<string, Sprite> _sprites = new Dictionary<string, Sprite>();

    public static Sprite Sprite(string name)
    {
        if (_sprites.TryGetValue(name, out var s) && s != null) return s;
        s = Resources.Load<Sprite>("UI/" + name);
        if (s == null) s = UISpriteFactory.CreateSprite(name);
        _sprites[name] = s;
        return s;
    }

    // ── Font ──────────────────────────────────────────────────────────────────
    static TMP_FontAsset _font;
    static bool _fontTried;

    public static TMP_FontAsset Font
    {
        get
        {
            if (_font != null) return _font;
            if (!_fontTried)
            {
                _fontTried = true;
                _font = Resources.Load<TMP_FontAsset>("UI/Fonts/MenuFont");
                if (_font == null)
                {
                    try { _font = TMP_FontAsset.CreateFontAsset("Bahnschrift", "Regular"); }
                    catch { _font = null; }
                    if (_font != null)
                    {
                        _font.name = "Bahnschrift (OS)";
                        // Anything Bahnschrift lacks falls through to TMP's default.
                        var def = TMP_Settings.defaultFontAsset;
                        if (def != null)
                        {
                            _font.fallbackFontAssetTable ??= new List<TMP_FontAsset>();
                            if (!_font.fallbackFontAssetTable.Contains(def))
                                _font.fallbackFontAssetTable.Add(def);
                        }
                    }
                }
            }
            return _font != null ? _font : TMP_Settings.defaultFontAsset;
        }
    }

    /// Re-font every TMP text under a root (baked scenes are authored with
    /// TMP's default font; this swaps in the menu font at runtime).
    public static void ApplyFont(GameObject root)
    {
        if (root == null) return;
        var f = Font;
        if (f == null) return;
        foreach (var t in root.GetComponentsInChildren<TMP_Text>(true))
            if (t.font != f) t.font = f;
    }

    /// Re-font every menu text in the loaded scene(s).
    public static void ApplyFontToScene()
    {
        var f = Font;
        if (f == null) return;
        foreach (var t in Object.FindObjectsByType<TMP_Text>(FindObjectsInactive.Include,
                                                             FindObjectsSortMode.None))
            if (t.font != f && t.GetComponentInParent<Canvas>(true) != null) t.font = f;
    }

    // ── Easing ────────────────────────────────────────────────────────────────
    public static float EaseOutCubic(float t) { t = Mathf.Clamp01(t); float u = 1f - t; return 1f - u * u * u; }
    public static float EaseInCubic(float t)  { t = Mathf.Clamp01(t); return t * t * t; }
    public static float EaseInOutCubic(float t)
    {
        t = Mathf.Clamp01(t);
        return t < 0.5f ? 4f * t * t * t : 1f - Mathf.Pow(-2f * t + 2f, 3f) * 0.5f;
    }
    public static float EaseOutBack(float t)
    {
        t = Mathf.Clamp01(t);
        const float c1 = 1.70158f, c3 = c1 + 1f;
        return 1f + c3 * Mathf.Pow(t - 1f, 3f) + c1 * Mathf.Pow(t - 1f, 2f);
    }
    /// Frame-rate independent exponential approach (unscaled time).
    public static float Damp(float current, float target, float rate) =>
        Mathf.Lerp(current, target, 1f - Mathf.Exp(-rate * Time.unscaledDeltaTime));
}
